import{_ as e,o as r,c as t,a2 as a}from"./chunks/framework.C-si7TFR.js";const f=JSON.parse('{"title":"Subworkflow Execution","description":"How to invoke sub-workflows synchronously or asynchronously and configure loop iterations.","frontmatter":{"title":"Subworkflow Execution","description":"How to invoke sub-workflows synchronously or asynchronously and configure loop iterations.","meta":[{"name":"keywords","content":"Sub-Process Node, Workflow Execution, Low-code, AI Workflow, Process Engine"}]},"headers":[],"relativePath":"sub_workflow.md","filePath":"sub_workflow.md"}'),n={name:"sub_workflow.md"};function i(s,o,l,u,c,h){return r(),t("div",null,[...o[0]||(o[0]=[a('<h2 id="subworkflow-execution" tabindex="-1">Subworkflow Execution <a class="header-anchor" href="#subworkflow-execution" aria-label="Permalink to &quot;Subworkflow Execution&quot;">​</a></h2><p>Subworkflows can be called for execution in either synchronous or asynchronous modes. The synchronous mode waits for the subworkflow to finish before continuing execution, while the asynchronous mode calls the subworkflow and proceeds without waiting for its completion.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><h3 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h3><p>Here, you can choose either a synchronous API or an asynchronous API workflow.</p><h3 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h3><ul><li><strong>Synchronous</strong>: Triggers the subworkflow execution and waits for it to finish before continuing.</li><li><strong>Asynchronous</strong>: Triggers the subworkflow execution without waiting for it to finish, allowing the process to continue.</li></ul><h3 id="workflow-parameter-passing" tabindex="-1">Workflow Parameter Passing <a class="header-anchor" href="#workflow-parameter-passing" aria-label="Permalink to &quot;Workflow Parameter Passing&quot;">​</a></h3><p>This allows for similar implementation of Post request JSON parameters for both synchronous and asynchronous APIs.</p><h2 id="loop-configuration" tabindex="-1">Loop Configuration <a class="header-anchor" href="#loop-configuration" aria-label="Permalink to &quot;Loop Configuration&quot;">​</a></h2><p>Subworkflow execution also supports setting a maximum loop count for executing the subworkflow.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><p>None</p>',15)])])}const p=e(n,[["render",i]]);export{f as __pageData,p as default};
